def thumbnails(event, ctx):
    out = []
    for record in event.records:
        target = "thumbs/" + record.key.split("/", 1)[-1]
        ctx.logger.info("thumbnail", extra={"key": record.key, "size": record.size, "target": target})
        out.append(target)
    return {"targets": out}
"}

